"use strict";(self.webpackChunk_egov3_system_design=self.webpackChunk_egov3_system_design||[]).push([[6552],{"./src/constants/mock/index.tsx"(__unused_webpack_module,__webpack_exports__,__webpack_require__){__webpack_require__.d(__webpack_exports__,{j:()=>htmlText});var htmlText='<div class="modal-body">\r\n    <div class="agreement" id="agreementid">\r\n        <h2>\r\n\n      <span style="color:#A52A2A">1 Общие положения</span>\r\n        </h2>\r\n\n      <p>1.1. Настоящее Пользовательское соглашение (далее - Соглашение) регламентирует взаимоотношения\n      между Владельцем, Администратором и Пользователем веб-портала «электронного правительства» и его\n      компонентов.</p>\r\n        <p>1.2. В настоящем Соглашении используются следующие понятия:</p>\r\n\n      <ul>\r\n            <li>1) веб-портал «электронного правительства» (далее – Портал) -\n      информационная система, представляющая собой единое окно доступа ко всей консолидированной\n      правительственной информации, включая нормативную правовую базу, и к государственным услугам,\n      оказываемым в электронной форме;</li>\r\n            <li>2) компоненты Портала – части Портала,\n      специализированные на предоставлении отдельных электронных услуг, информации и (или) сервисов;\n      </li>\r\n            <li>3) электронная услуга (далее - Услуга) - предоставление физическим и\n      юридическим лицам информационных, интерактивных и транзакционных услуг с применением информационных\n      технологий;</li>\r\n            <li>4) владелец Портала и его компонентов (далее - Владелец)\n      уполномоченный орган в сфере информатизации;</li>\r\n            <li>5) пользователь Портала и его\n      компонентов (далее - Пользователь) - любое физическое или юридическое лицо, принявшее условия\n      настоящего Соглашения, зарегистрированное на Портале и в его компонентах, пользующееся услугами\n      Портала и его компонентов для получения необходимых ему электронных информационных ресурсов,\n      информации или интерактивных государственных услуг в рамках действующего законодательства Республики\n      Казахстан;</li>\r\n            <li>6) администратор Портала и его компонентов (далее -\n      Администратор) – акционерное общество «Национальные информационные технологии»;</li>\r\n\n      <li>7) услугодатель - центральные государственные органы, загранучреждения Республики Казахстан,\n      местные исполнительные органы областей, городов республиканского значения, столицы, районов,\n      городов областного значения, акимы районов в городе, городов районного значения, поселков, сел,\n      сельских округов, а также физические и юридические лица, оказывающие государственные услуги в\n      соответствии с законодательством Республики Казахстан;</li>\r\n            <li>8) короткое\n      текстовое сообщение (далее – SMS-сообщение) – услуга, оказываемая оператором сотовой связи по\n      приему и передаче информации посредством сети сотовой связи;</li>\r\n            <li>9) «мобильное\n      правительство» - компонент Портала, – информационная система, предоставляющая доступ к\n      государственным Услугам в электронной форме и иным Услугам, оказываемым в электронной форме,\n      посредствоРм технологий сотовой связи и Интернет;</li>\r\n            <li>10) PUSH - краткие\n      всплывающие уведомления мобильного приложения Пользователей «мобильного правительства», которые\n      появляются на экране мобильного телефона и сообщают о важных событиях и обновлениях;</li>\r\n\n      <li>11) мобильное приложение - это программа, установленная и запущенная на мобильном устройстве\n      Пользователя, и предоставляющая доступ к государственным услугам и иным услугам, оказываемым\n      посредством «мобильного правительства» в электронной форме, посредством сети сотовой связи и\n      Интернет;</li>\r\n            <li>12) третье лицо - юридическое или физическое лицо, не являющееся\n      государственным органом, наделенной правом получения от Пользователя соответствующей\n      Конфиденциальной информации по соглашению или ином законном основании;</li>\r\n\n      <li>13) субъект оказания услуг – физическое или юридическое лицо, оказывающее электронные услуги\n      посредством Портала;</li>\r\n            <li>14) электронная цифровая подпись (далее – ЭЦП) -\n      набор электронных цифровых символов, созданный средствами электронной цифровой подписи и\n      подтверждающий достоверность электронного документа, его принадлежность и неизменность содержания.\n      </li>\r\n        </ul>\r\n        <p>1.3. Все иные термины и определения, используемые в настоящем\n      Соглашении, истолковываются в соответствии с действующим законодательством Республики Казахстан.\n      </p>\r\n        <h2>\r\n            <span style="color:#A52A2A">2 Предмет Соглашения</span>\r\n\n      </h2>\r\n        <p>2.1. Настоящее Соглашение является публичной офертой. Получая доступ к\n      материалам Портала и его компонентам, Пользователь считается присоединившимся и принявшим все\n      условия настоящего Соглашения.</p>\r\n        <p>2.2. Администратор вправе с согласия Владельца\n      в любое время в одностороннем порядке изменять условия настоящего Соглашения. Изменения вступают\n      в силу по истечении 3 (трех) дней с момента размещения новой версии Соглашения на Портале и\n      подписания новой версии соглашения всеми Пользователями повторно при авторизации с одновременной\n      утратой предыдущей версии Соглашения.</p>\r\n        <p>2.3. При несогласии Пользователя с\n      внесенными изменениями он обязан отказаться от доступа к Порталу и его компонентам и прекратить\n      использование материалов и сервисов Портала и его компонентов.</p>\r\n\n      <p>2.4. Использование компонентов Портала осуществляется Пользователем согласно инструкциям по\n      их использованию, размещенным в Личном кабинете Портала.</p>\r\n        <p>2.5. Оказание услуг\n      посредством SMS – сообщений, получение уведомлений, в том числе информационного характера, в\n      формате SMS - сообщений являются платными и оплачиваются за счет телефонного баланса Пользователя.\n      Стоимость SMS – сообщения тарифицируется текущим тарифным планом Пользователя. PUSH-уведомления\n      являются бесплатными.</p>\r\n        <p>2.6. За достоверность сведений, полученных в результате\n      оказания услуг посредством Портала и его компонентов, несет ответственность услугодатель или\n      субъект оказания Услуг.</p>\r\n        <p>2.7. Электронный адрес, указанный Пользователем в форме\n      регистрации на Портале предназначен для получения уведомлений в случае:</p>\r\n\n      <ul>\r\n            <li>1) подписки Пользователем на получение служебных уведомлений;</li>\r\n\n      <li>2) восстановления пароля, получения временного пароля;</li>\r\n\n      <li>3) получения сгенерированного нового пароля.</li>\r\n        </ul>\r\n\n      <p>2.8. Подписывая настоящее Соглашение, Пользователь берет на себя ответственность за сбор,\n      обработку, хранение, выгрузку и использование его персональных данных граждан, иностранцев и\n      лиц без гражданства имеющейся у государственных органов и иной информации представленной\n      Пользователем на Портале информации в целях оказания ему услуг посредством Портала и его\n      компонентов, а также улучшения качества предоставляемых (оказываемых) услуг.</p>\r\n\n      <h2>\r\n            <span style="color:#A52A2A">3 Права и обязанности Сторон</span>\r\n\n      </h2>\r\n        <p>\r\n            <strong>3.1. Владелец и Администратор вправе:</strong>\r\n\n      </p>\r\n        <p>3.1.1. В случае необходимости проверять достоверность введенных данных\n      Пользователя, в том числе путем обращения в государственные органы и иные организации.</p>\r\n\n      <p>3.1.2. В случае нарушения Пользователем условий настоящего Соглашения отказать в регистрации\n      Пользователя, удалить или блокировать учетную запись Пользователя.</p>\r\n\n      <p>3.1.3. Направлять Пользователю уведомления информационного характера в формате SMS –\n      сообщений и PUSH - уведомлений.</p>\r\n        <p>3.1.4. В случае, если действия Пользователя\n      создают угрозы для доступа других Пользователей или для данных других Пользователей,\n      Администратор вправе приостановить или прервать сессию Пользователя и временно заблокировать\n      его запросы.</p>\r\n        <p>\r\n            <strong>3.2. Пользователь вправе:</strong>\r\n\n      </p>\r\n        <p>3.2.1. Получать консультационную и практическую помощь от Администратора в\n      части пользования Порталом и его компонентами, обратившись в Единый контакт-центр по номеру\n      1414.</p>\r\n        <p>\r\n            <strong>3.3. Владелец и Администратор обязаны:\n      </strong>\r\n        </p>\r\n        <p>3.3.1. Обеспечить конфиденциальность персональных\n      данных Пользователя путем недопущения их разглашения без согласия Пользователя или его законного\n      представителя либо наличия иного законного основания, согласно текущему законодательству\n      Республики Казахстан.</p>\r\n        <p>3.3.2. Обеспечить функционирование Портала и его\n      компонентов.</p>\r\n        <p>3.3.3. Сохранять в тайне от посторонних лиц, не связанных с\n      процессом обмена данными, вверенный ему пароль для доступа Пользователя, за исключением случаев,\n      предусмотренных законодательством Республики Казахстан.</p>\r\n        <p>\r\n\n      <strong>3.4. Пользователь обязан:</strong>\r\n        </p>\r\n        <p>3.4.1. Для получения\n      услуг Портала и его компонентов:</p>\r\n        <ul>\r\n            <li>1) иметь ИИН (для\n      физических лиц) или БИН (для юридических лиц);</li>\r\n            <li>2) до регистрации иметь\n      действующую ЭЦП, выданную Национальным удостоверяющим центром РК, применяемую в сфере\n      «электронного правительства»;</li>\r\n            <li>3) пройти процедуру регистрации.</li>\r\n\n      </ul>\r\n        <p>3.4.2. Предоставить Владельцу и Администратору точную и полную информацию\n      по пунктам, предлагаемым в форме регистрации на Портале или при использовании его компонентов.\n      </p>\r\n        <p>3.4.3. Не предпринимать действий, которые могут рассматриваться как\n      нарушающие законодательства Республики Казахстан или нормы международного права, в том числе\n      в сфере интеллектуальной собственности, авторских и/или смежных правах, а также любых действий,\n      которые приводят или могут привести к нарушению нормальной работы и сервисов Портала и его\n      компонентов.</p>\r\n        <p>3.4.4. Не допускать противоречия комментариев и иных записей\n      Пользователя на Портале и его компонентах требованиям законодательства Республики Казахстан и\n      общепринятым нормам морали и нравственности.</p>\r\n        <p>3.4.5. При работе на Портале\n      не выдавать себя за другое лицо, не использовать материалы, содержащие вирусы или другое\n      вредоносное программное обеспечение, использовать собственную ЭЦП.</p>\r\n        <p>3.4.6.\n      Не использовать Портал и полученную на Портале информацию в целях терроризма, экстремизма,\n      разжигания межнациональной розни и в иных запрещенных законодательством Республики Казахстан\n      целях.</p>\r\n        <p>3.4.7. Надлежащим образом  соблюдать  условия настоящего Соглашения;\n      </p>\r\n        <h2>\r\n            <span style="color:#A52A2A">4 Ответственность сторон\n      </span>\r\n        </h2>\r\n        <p>4.1. В случае нарушения условий настоящего Соглашения,\n      повлекшего причинение вреда всем или одной из сторон Соглашения, виновная сторона несет\n      ответственность в соответствии с законодательством Республики Казахстан.</p>\r\n\n      <p>4.2. Администратор не несет ответственности за технические временные сбои и перерывы в\n      работе Портала и его компонентах, возникшие по независящим от Администратора, Владельца\n      причинам или в случае проведения плановых мероприятий по обслуживанию Портала и его компонентов.\n      </p>\r\n        <p>4.3. Владелец и Администратор не несут ответственности за временные сбои и\n      перерывы в работе линий связи, иные аналогичные сбои, а также за неполадки компьютера,\n      мобильного устройства связи, с которого Пользователь осуществляет доступ к Порталу и его\n      компонентам.</p>\r\n        <p>4.4. Владелец и Администратор не несут ответственности перед\n      Пользователем за действия других Пользователей, услугодателей и любых других участников\n      Портала, и его компонентов.</p>\r\n        <p>4.5. Владелец и Администратор не несут\n      ответственности за любой прямой, косвенный ущерб, включая упущенную выгоду, ущерб от\n      использования, потерю данных или какие-либо другие нематериальные потери, ущерб репутации и\n      иной ущерб, возникающий вследствие:</p>\r\n        <ul>\r\n            <li>1) пользования\n      или невозможности пользования Порталом, и его компонентами Пользователями;</li>\r\n\n      <li>2) изменения условий Соглашения Владельцем и (или) Администратором.</li>\r\n\n      </ul>\r\n        <p>4.6. Пользователь несет полную ответственность:</p>\r\n\n      <ul>\r\n            <li>• за достоверность предоставляемых данных при регистрации на Портале\n      и его компонентах, а также за несвоевременное обновление и корректировку данных, указанных\n      на Портале.</li>\r\n            <li>• за действия Третьих лиц, которым был предоставлен\n      Пользователем доступ на Портал и его компоненты.</li>\r\n        </ul>\r\n\n      <p>4.7. Пользователь принимает на себя все риски и возможный ущерб, возникший в результате\n      предоставления ими недостоверных сведений о себе, а также за передачу собственных данных,\n      третьим лицам связанных с регистрацией на Портале и его компонентах, и использованием его\n      компонентов.</p>\r\n        <p>4.8. При использовании Портала Пользователь не вправе:</p>\r\n\n      <ul>\r\n            <li>1) нарушать права третьих лиц, в том числе несовершеннолетних лиц\n      и/или причинять им вред в любой форме;</li>\r\n            <li>2) выдавать себя за другого\n      человека или представителя организации и/или сообщества без достаточных на то прав, а также\n      применять любые другие формы и способы незаконного представительства других лиц в сети;\n      </li>\r\n            <li>3) нарушать нормальную работу Портала;</li>\r\n\n      <li>4) содействовать действиям, направленным на нарушение ограничений и запретов, налагаемых\n      Соглашением;</li>\r\n            <li>5) другим образом нарушать нормы законодательства\n      Республики Казахстан, в том числе нормы международного права.</li>\r\n        </ul>\r\n\n      <h2>\r\n            <span style="color:#A52A2A">5 Прочие положения</span>\r\n\n      </h2>\r\n        <p>5.1. Все возможные споры, вытекающие из настоящего Соглашения или\n      связанные с ним, подлежат разрешению в соответствии с действующим законодательством\n      Республики Казахстан.</p>\r\n        <p>5.2. Бездействие со стороны Администратора в случае\n      нарушения кем-либо из Пользователей положений Соглашения не лишает Владельца права\n      предпринять позднее соответствующие действия в защиту своих интересов и защиту имущественных\n      и неимущественных прав на охраняемые в соответствии с законодательством материалы\n      Портала.</p>\r\n        <p>5.3. Настоящее Соглашение вступает в силу при первом посещении\n      Портала Пользователем и действует между Пользователем и Администратором на протяжении\n      всего периода использования Пользователем Портала.</p>\r\n        <p>5.4. Настоящее\n      Соглашение регулируется и толкуется в соответствии с законодательством Республики Казахстана.\n      Вопросы, не урегулированные Соглашением, подлежат разрешению в соответствии с\n      законодательством Республики Казахстан.</p>\r\n    </div>\r\n</div>'},"./src/stories/CardWrapperItem.tsx"(__unused_webpack_module,__webpack_exports__,__webpack_require__){__webpack_require__.d(__webpack_exports__,{Z:()=>CardWrapperItem});var react_jsx_runtime__WEBPACK_IMPORTED_MODULE_0__=__webpack_require__("./node_modules/react/jsx-runtime.js"),CardWrapperItem=function CardWrapperItem(_ref){var children=_ref.children;return(0,react_jsx_runtime__WEBPACK_IMPORTED_MODULE_0__.jsx)("div",{style:{display:"flex",justifyContent:"center",minHeight:"100px"},children:(0,react_jsx_runtime__WEBPACK_IMPORTED_MODULE_0__.jsx)("div",{style:{backgroundColor:"bisque",padding:"9px",display:"flex",flexDirection:"column",borderRadius:"20px",justifyContent:"center"},children})})};try{CardWrapperItem.displayName="CardWrapperItem",CardWrapperItem.__docgenInfo={description:"",displayName:"CardWrapperItem",props:{}},"undefined"!=typeof STORYBOOK_REACT_CLASSES&&(STORYBOOK_REACT_CLASSES["src/stories/CardWrapperItem.tsx#CardWrapperItem"]={docgenInfo:CardWrapperItem.__docgenInfo,name:"CardWrapperItem",path:"src/stories/CardWrapperItem.tsx#CardWrapperItem"})}catch(__react_docgen_typescript_loader_error){}}}]);
//# sourceMappingURL=6552.6da43f8f.iframe.bundle.js.map